+        IndexNameExpressionResolver indexNameExpressionResolver,
+        Supplier<RepositoriesService> repositoriesServiceSupplier
+    ) {
+        grokHelper.finishInitializing(threadPool);
+        return List.of();
+    }
+
+    public NamedGroupExtractor.GrokHelper grokHelper() {
+        return grokHelper;
+    }
+}
