+            bigArray[i] = (byte) i;
+        }
+        byte[] smallArray = new byte[MAX_CHUNK_SIZE];
+        System.arraycopy(bigArray, 0, smallArray, 0, MAX_CHUNK_SIZE);
+        ByteArrayInputStream is = new ByteArrayInputStream(bigArray);
