+            if (handlers.containsKey(action)) {
+                BiConsumer<ActionRequest, ActionListener<?>> biConsumer =
+                    (BiConsumer<ActionRequest, ActionListener<?>>) handlers.get(action);
+                biConsumer.accept(request, listener);
